// Nagar Drishti Civic Category & Department Knowledge Matrix
const CATEGORY_MAP = {
  'road-damage': {
    catId: 'c1111111-1111-1111-1111-111111111111',
    catName: 'Road Damage & Potholes',
    deptId: 'd1111111-1111-1111-1111-111111111111',
    deptName: 'Public Works Department (PWD)'
  },
  'garbage': {
    catId: 'c2222222-2222-2222-2222-222222222222',
    catName: 'Garbage & Waste Accumulation',
    deptId: 'd2222222-2222-2222-2222-222222222222',
    deptName: 'Solid Waste Management'
  },
  'water-leak': {
    catId: 'c3333333-3333-3333-3333-333333333333',
    catName: 'Water Pipeline Leakage / Burst',
    deptId: 'd3333333-3333-3333-3333-333333333333',
    deptName: 'Delhi Jal Board (Water & Sewage)'
  },
  'streetlights': {
    catId: 'c4444444-4444-4444-4444-444444444444',
    catName: 'Broken Streetlights',
    deptId: 'd4444444-4444-4444-4444-444444444444',
    deptName: 'Electricity & Power Distribution'
  },
  'sewage': {
    catId: 'c5555555-5555-5555-5555-555555555555',
    catName: 'Sewage Overflow & Blocked Drains',
    deptId: 'd3333333-3333-3333-3333-333333333333',
    deptName: 'Delhi Jal Board (Water & Sewage)'
  },
  'trees': {
    catId: 'c6666666-6666-6666-6666-666666666666',
    catName: 'Fallen Trees & Obstructions',
    deptId: 'd5555555-5555-5555-5555-555555555555',
    deptName: 'Horticulture & Public Parks'
  }
};

const items = $input.all();
const results = [];

for (const item of items) {
  const payload = item.json.body || item.json;
  const title = String(payload.title || '').toLowerCase();
  const desc = String(payload.description || '').toLowerCase();
  const loc = String(payload.location_text || payload.location || '').toLowerCase();
  const combined = `${title} ${desc} ${loc}`;

  let matchedKey = null;
  if (/pothole|crater|asphalt|paver|sinkhole|road damage|broken road/i.test(combined)) matchedKey = 'road-damage';
  else if (/garbage|waste|trash|dumpster|litter|sanitation/i.test(combined)) matchedKey = 'garbage';
  else if (/water|pipeline|burst|leak|water supply/i.test(combined)) matchedKey = 'water-leak';
  else if (/streetlight|street light|dark street|lamp post|flickering|electric/i.test(combined)) matchedKey = 'streetlights';
  else if (/sewage|drain|manhole|sewer|dirty water/i.test(combined)) matchedKey = 'sewage';
  else if (/tree|branch|park|greenery|pruning/i.test(combined)) matchedKey = 'trees';

  const matched = matchedKey ? CATEGORY_MAP[matchedKey] : null;

  results.push({
    json: {
      complaint_id: payload.complaint_id || payload.id || null,
      matched_category: matched ? matched.catName : 'Unknown',
      category_id: matched ? matched.catId : null,
      department_id: matched ? matched.deptId : null,
      department_name: matched ? matched.deptName : null,
      confidence_score: matched ? 0.96 : 0.40,
      workflow: 'Workflow_A_Department_Auto_Assignment',
      timestamp: new Date().toISOString()
    }
  });
}

return results;

